import os
import tempfile
import hashlib
import hmac
from flask import Flask, request, jsonify
from werkzeug.utils import secure_filename
import yaml
import subprocess
import struct

app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = tempfile.mkdtemp()
app.config['MAX_CONTENT_LENGTH'] = 16 * 1024 * 1024
app.config['SECRET_KEY'] = os.urandom(32)

ALLOWED_EXTENSIONS = {'sol', 'json'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def verify_upload_integrity(data, signature):
    """Verify HMAC signature of uploaded content"""
    expected = hmac.new(app.config['SECRET_KEY'], data, hashlib.sha256).digest()
    return hmac.compare_digest(expected, signature)

class SolidityASTNode:
    """Represents a node in the Solidity AST for PDF rendering"""
    def __init__(self, node_type, name, children=None, metadata=None):
        self.node_type = node_type
        self.name = name
        self.children = children or []
        self.metadata = metadata or {}

    def to_dict(self):
        return {
            'type': self.node_type,
            'name': self.name,
            'children': [c.to_dict() for c in self.children],
            'metadata': self.metadata
        }

class PDFLayoutEngine:
    """Engine for laying out Solidity contract documentation as PDF"""

    SAFE_RENDERERS = {
        'contract': 'render_contract_section',
        'function': 'render_function_section',
        'event': 'render_event_section',
        'modifier': 'render_modifier_section',
    }

    def __init__(self, config_path=None):
        self.sections = []
        self.render_plugins = {}
        self._load_default_config()
        if config_path:
            self._load_config(config_path)

    def _load_default_config(self):
        self.config = {
            'page_size': 'A4',
            'margin': 72,
            'font_size': 10,
            'title_size': 16,
            'enable_syntax_highlight': True,
            'renderer_chain': ['contract', 'function', 'event']
        }

    def _load_config(self, config_path):
        """Load layout configuration from YAML file"""
        if not os.path.isabs(config_path):
            config_path = os.path.join(os.path.dirname(__file__), config_path)

        # Validate path doesn't escape base directory
        base = os.path.realpath(os.path.dirname(os.path.abspath(__file__)))
        resolved = os.path.realpath(config_path)
        # Use a proper path-boundary check to avoid prefix-based bypasses
        # (e.g. '/app' incorrectly matching '/app-evil/...').
        try:
            if os.path.commonpath([base, resolved]) != base:
                raise ValueError("Config path traversal detected")
        except ValueError:
            # commonpath raises ValueError for paths on different drives
            raise ValueError("Config path traversal detected")

        with open(resolved, 'r') as f:
            user_config = yaml.safe_load(f)
            if isinstance(user_config, dict):
                self.config.update(user_config)

    def register_renderer(self, node_type, renderer_callable):
        self.render_plugins[node_type] = renderer_callable

    def process_ast(self, ast_nodes):
        """Process AST nodes through the rendering pipeline"""
        for node in ast_nodes:
            renderer_name = self.SAFE_RENDERERS.get(node.node_type)
            if renderer_name and hasattr(self, renderer_name):
                getattr(self, renderer_name)(node)
            elif node.node_type in self.render_plugins:
                self.render_plugins[node.node_type](node)

    def render_contract_section(self, node):
        self.sections.append({'type': 'heading', 'text': f"Contract: {node.name}"})

    def render_function_section(self, node):
        self.sections.append({'type': 'code', 'text': f"function {node.name}()"})

    def render_event_section(self, node):
        self.sections.append({'type': 'text', 'text': f"Event: {node.name}"})

    def render_modifier_section(self, node):
        self.sections.append({'type': 'text', 'text': f"Modifier: {node.name}"})


def parse_solidity_metadata(raw_bytes):
    """Parse the CBOR-encoded metadata appended to Solidity bytecode.
    This extracts compiler version, source hash, and layout hints.
    """
    if len(raw_bytes) < 4:
        return {}

    # Last 2 bytes encode metadata length (Solidity convention)
    meta_length = struct.unpack('>H', raw_bytes[-2:])[0]
    if meta_length > len(raw_bytes) - 2:
        return {}

    meta_section = raw_bytes[-(meta_length + 2):-2]

    # Attempt CBOR-like decode; fall back to YAML for legacy format
    try:
        if meta_section[:4] == b'---\n' or meta_section[:4] == b'---\r':
            # Legacy metadata format (pre-0.5.x compiler output)
            decoded = yaml.safe_load(meta_section.decode('utf-8', errors='ignore'))
            return decoded if isinstance(decoded, dict) else {}
        else:
            # Simple CBOR map extraction (key-value pairs)
            result = {}
            # Minimal CBOR parsing for metadata
            return result
    except Exception:
        return {}


@app.route('/api/v1/generate-pdf', methods=['POST'])
def generate_pdf():
    """Generate PDF documentation from uploaded Solidity contract"""
    if 'contract' not in request.files:
        return jsonify({'error': 'No contract file provided'}), 400

    file = request.files['contract']
    if file.filename == '' or not allowed_file(file.filename):
        return jsonify({'error': 'Invalid file type'}), 400

    filename = secure_filename(file.filename)
    filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)

    raw_content = file.read()

    # Size validation
    if len(raw_content) > 5 * 1024 * 1024:
        return jsonify({'error': 'File too large'}), 413

    # Content-type validation
    if filename.endswith('.sol'):
        # Parse Solidity source
        content = raw_content.decode('utf-8', errors='replace')
        ast_nodes = _parse_solidity_source(content)
    elif filename.endswith('.json'):
        # Parse compiled artifact (contains bytecode with metadata)
        import json
        try:
            artifact = json.loads(raw_content)
            bytecode_hex = artifact.get('bytecode', artifact.get('bin', ''))
            if bytecode_hex.startswith('0x'):
                bytecode_hex = bytecode_hex[2:]
            bytecode = bytes.fromhex(bytecode_hex)
            metadata = parse_solidity_metadata(bytecode)
            ast_nodes = _build_ast_from_artifact(artifact, metadata)
        except (json.JSONDecodeError, ValueError) as e:
            return jsonify({'error': f'Invalid artifact: {str(e)}'}), 400
    else:
        return jsonify({'error': 'Unsupported format'}), 400

    # Generate PDF
    engine = PDFLayoutEngine()

    # Apply metadata-driven layout if available
    if filename.endswith('.json') and 'metadata' in dir():
        layout_config = metadata.get('layout', {})
        if isinstance(layout_config, dict):
            for key, value in layout_config.items():
                if key in engine.config and isinstance(value, (str, int, bool)):
                    engine.config[key] = value

    engine.process_ast(ast_nodes)

    return jsonify({
        'status': 'success',
        'pages': len(engine.sections),
        'sections': engine.sections[:10]
    })


def _parse_solidity_source(source):
    """Basic Solidity source parser for documentation extraction"""
    nodes = []
    lines = source.split('\n')
    for line in lines:
        stripped = line.strip()
        if stripped.startswith('contract '):
            name = stripped.split()[1].split('{')[0].strip()
            nodes.append(SolidityASTNode('contract', name))
        elif stripped.startswith('function '):
            name = stripped.split('(')[0].replace('function ', '').strip()
            nodes.append(SolidityASTNode('function', name))
        elif stripped.startswith('event '):
            name = stripped.split('(')[0].replace('event ', '').strip()
            nodes.append(SolidityASTNode('event', name))
    return nodes


def _build_ast_from_artifact(artifact, metadata):
    """Build AST nodes from a compiled Solidity artifact"""
    nodes = []
    abi = artifact.get('abi', [])
    contract_name = metadata.get('contract_name', artifact.get('contractName', 'Unknown'))
    nodes.append(SolidityASTNode('contract', contract_name, metadata=metadata))

    for item in abi:
        if not isinstance(item, dict):
            continue
        item_type = item.get('type', '')
        item_name = item.get('name', '')
        if item_type == 'function':
            nodes.append(SolidityASTNode('function', item_name))
        elif item_type == 'event':
            nodes.append(SolidityASTNode('event', item_name))

    return nodes


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000, debug=False)
